#!/bin/bash
#
# Launch hook for `code`: give each project's window its own class and taskbar
# icon, so several VS Code windows can be told apart.
#
# ~/bin/code (generated by appimage.sh) runs this as `code.sh <cli> [args...]`
# on every launch. It always ends by exec'ing the CLI with the arguments it was
# given, so `code --version`, `code --wait file`, `code --install-extension` and
# the rest behave exactly as before.
#
# When the arguments open a single folder, the window that folder ends up in is
# retagged in the background:
#
#   class   code-<path with dashes>, e.g. code-home-jeffjose-scripts-project1
#   icon    <folder>/.icon.png, if there is one. Without it an icon is drawn: a
#           Solar bold-duotone glyph in a Radix colour, edge to edge, both worked
#           out from the folder's path, so a project keeps its look from one
#           launch and one machine to the next. A drawn icon lives in
#           ~/.cache/code-icons/<path with dashes>.png, not in the project, so
#           it never shows up as an untracked file — drop a .icon.png in and
#           the next `code <folder>` uses that instead.
#
# It stays the one regular VS Code: same instance, same settings, extensions
# and sign-ins. `code --class` would be the obvious way and does nothing — every
# window comes up as "code" whatever is passed — and all windows share one
# process anyway. So the window is retagged after it opens instead, which needs
# X11: WM_CLASS and _NET_WM_ICON are properties any client may rewrite. A
# native Wayland window has neither; its app id is fixed by the app. There this
# only works with VS Code running under XWayland (--ozone-platform=x11).
#
# Nothing here may print on the success path or fail the launch: tools read the
# output of `code`, and a broken hook must not cost you the editor.
#
# Jeffrey Jose | Oct 10, 2026
#

cli="$1"
shift

XWINPROP="$HOME/dotfiles/scripts/utils/xwinprop.py"
APP_DIR="$HOME/.local/share/applications"
ICON_SIZE=64

# Pick the folder being opened out of the arguments. Anything that is not
# plainly "open this one folder" is left alone: options whose value is itself a
# directory, and the ones that put a folder into a window that already belongs
# to another project.
dir=""
retag=1
args=()
for arg in "$@"; do
  case "$arg" in
    --user-data-dir | --user-data-dir=* | --extensions-dir | --extensions-dir=* | \
      --add | -a | --diff | -d | --merge | -m | --folder-uri | --file-uri | --remote | --remote=*)
      retag=0 ;;
    -*) ;;
    *)
      if [ -d "$arg" ]; then
        # Two folders make a multi-root window, named after neither.
        if [ -n "$dir" ]; then retag=0; fi
        dir="$arg"
      fi
      ;;
  esac
  args+=("$arg")
done

if [ $retag -eq 0 ] || [ -z "$dir" ]; then
  exec "$cli" "${args[@]}"
fi

dir=$(realpath "$dir")
name=$(basename "$dir")
# Everything below is keyed by the folder's full path, not its name, so that
# ~/work/api and ~/play/api are two projects. The path is taken relative to
# $HOME, which keeps the checksum — and with it the colour and glyph — the
# same on every machine that has the project in the same place.
seed=$(printf '%s' "${dir/#$HOME/\~}" | cksum | cut -d' ' -f1)
# The path with everything but plain characters turned into dashes:
# /home/jeffjose/scripts/project1 -> -home-jeffjose-scripts-project1. It names
# the cached icon, and after "code" the class — which is matched against
# .desktop file names, hence the plain characters.
slug=$(printf '%s' "$dir" | tr -c 'A-Za-z0-9._-' '-')
class="code$slug"

# Radix Colors, step 9 of each scale — the solid, most saturated step.
COLOURS=(
  '#e54d2e' '#e5484d' '#e54666' '#e93d82' '#d6409f' # tomato red ruby crimson pink
  '#ab4aba' '#8e4ec6' '#6e56cf' '#5b5bd6' '#3e63dd' # plum purple violet iris indigo
  '#0090ff' '#00a2c7' '#12a594' '#29a383' '#30a46c' # blue cyan teal jade green
  '#46a758' '#ad7f58' '#f76b15' '#a18072' '#978365' # grass brown orange bronze gold
  '#7ce2fe' '#86ead4' '#bdee63' '#ffe629' '#ffc53d' # sky mint lime yellow amber
)

# Solar (CC BY 4.0), bold duotone: solar:<glyph>-bold-duotone on Iconify.
GLYPHS=(
  atom balloon basketball bell bicycling bolt bone bookmark bowling bug camera
  cat chef-hat cloud compass cpu-bolt crown cup-hot cup-star database donut
  dumbbell earth fire flag flame folder gamepad ghost gift glasses global hanger
  headphones-round heart home infinity key ladle leaf lightbulb magic-stick-3
  magnet map medal-ribbon-star moon music-note notebook paint-roller palette
  paw plain planet rocket rugby running shield skateboard sledgehammer snowflake
  star suitcase sun target tea-cup telescope test-tube ufo-3 umbrella waterdrop
  wheel wind
)

# draw_icon <file>: a Solar glyph in a Radix colour, on nothing — no tile behind
# it, and trimmed and scaled until it all but touches the edges, because at
# taskbar size every pixel spent on a background or a margin is one the glyph
# does not get.
#
# Both are picked by the project's checksum — pseudo-random, but the same every
# time for the same project — from separate slices of it, so that two projects
# landing on one colour still get different glyphs.
#
# The glyph comes from the Iconify API, already tinted. That is one short
# request the first time a project is opened; offline, or with the API down,
# the icon is the first letter of the folder's name instead.
draw_icon() {
  local colour glyph svg initial
  colour=${COLOURS[$((seed % ${#COLOURS[@]}))]}
  glyph=${GLYPHS[$((seed / ${#COLOURS[@]} % ${#GLYPHS[@]}))]}
  svg=$(mktemp --suffix=.svg) || return 1

  if curl -fsL --max-time 3 -o "$svg" \
    "https://api.iconify.design/solar/$glyph-bold-duotone.svg?color=%23${colour#\#}&width=512&height=512" &&
    command grep -q '<svg' "$svg"; then
    # A duotone glyph marks its lighter half with opacity=".5", on single
    # shapes or on a group of them, and ImageMagick's SVG reader ignores that —
    # everything comes out solid. So build the two tones by hand: the whole
    # glyph at half strength, and on top of it the glyph with the lighter
    # shapes cut out.
    sed -E 's/<g opacity="[^"]*">(<[a-z]+[^>]*\/>)*<\/g>//g; s/<[a-z]+[^>]* opacity="[^"]*"[^>]*\/>//g' \
      "$svg" >"$svg.solid.svg" &&
      convert -background none "$svg" -channel A -evaluate multiply 0.5 +channel \
        \( -background none "$svg.solid.svg" \) -composite "$svg.png"
  else
    initial=$(printf '%s' "$name" | tr -cd '[:alnum:]' | cut -c1 | tr '[:lower:]' '[:upper:]')
    convert -background none -fill "$colour" -font DejaVu-Sans-Bold -pointsize 400 \
      label:"${initial:-?}" "$svg.png"
  fi &&
    # Cut the empty border off, scale the longer side to just short of the full
    # 256 — flush against the edge it crowds its neighbours in the taskbar —
    # and centre it.
    convert "$svg.png" -trim +repage -resize 232x232 -background none \
      -gravity center -extent 256x256 "$1"
  local status=$?
  rm -f "$svg" "$svg.png" "$svg.solid.svg"
  return $status
}

# The project's own icon wins; otherwise draw one, once, into the cache.
icon="$dir/.icon.png"
if [ ! -f "$icon" ]; then
  icon="${XDG_CACHE_HOME:-$HOME/.cache}/code-icons/$slug.png"
  if [ ! -f "$icon" ] && command -v convert >/dev/null 2>&1; then
    mkdir -p "${icon%/*}" 2>/dev/null && draw_icon "$icon" 2>/dev/null
  fi
fi

# A launcher per project. Docks that go by class rather than by the window's own
# icon (GNOME, KDE) find the icon through StartupWMClass here, and the project
# gets an entry in the application menu.
write_launcher() {
  local desktop_icon="vscode"
  [ -f "$icon" ] && desktop_icon="$icon"
  mkdir -p "$APP_DIR" || return 0
  cat >"$APP_DIR/$class.desktop" <<EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=$name (VS Code)
Comment=Open $dir in VS Code
Exec=$HOME/bin/code "$dir"
Icon=$desktop_icon
Categories=Development;
StartupWMClass=$class
StartupNotify=true
EOF
}
write_launcher 2>/dev/null

if [ -z "${DISPLAY:-}" ] || ! command -v xprop >/dev/null 2>&1; then
  exec "$cli" "${args[@]}"
fi

# Every VS Code window on the display, as "id<TAB>title". code-* counts too, so
# a window retagged by an earlier launch is still found.
code_windows() {
  local w c
  for w in $(xprop -root _NET_CLIENT_LIST 2>/dev/null | sed 's/.*# //; s/,//g'); do
    c=$(xprop -id "$w" WM_CLASS 2>/dev/null | cut -d'"' -f4)
    case "$c" in code | Code | code-*) ;; *) continue ;; esac
    printf '%s\t%s\n' "$w" "$(xprop -id "$w" _NET_WM_NAME 2>/dev/null | cut -d'"' -f2)"
  done
}

# The window for this project: one that was not there before the launch, or —
# when the project was already open and VS Code just raised it — the one whose
# title names the folder ("main.py - project1 - Visual Studio Code").
#
# find_window <new|any>: print the id of a matching window, new ones only or any
find_window() {
  local w title
  while IFS=$'\t' read -r w title; do
    [[ "$title" =~ (^|\ -\ )"$name"\ -\ Visual\ Studio\ Code$ ]] || continue
    if [ "$1" = "new" ] && command grep -qxF -- "$w" <<<"$before"; then continue; fi
    echo "$w"
    return 0
  done < <(code_windows)
  return 1
}

retag_window() {
  local wid="" i
  # A new window can take a while to appear; an existing one is there at once,
  # so settle for it after a couple of seconds of nothing new.
  for i in $(seq 1 60); do
    wid=$(find_window new) && break
    if [ "$i" -ge 8 ] && wid=$(find_window any); then break; fi
    sleep 0.25
  done
  [ -n "$wid" ] || return 0

  if [ -f "$icon" ] && command -v convert >/dev/null 2>&1; then
    convert "$icon" -resize "${ICON_SIZE}x${ICON_SIZE}!" -depth 8 rgba:- |
      "$XWINPROP" "$wid" --class "$class" --icon "$ICON_SIZE"
  else
    "$XWINPROP" "$wid" --class "$class"
  fi
}

# Taken before the launch, so the new window can be told from the old ones. The
# retagging then waits for the window in the background, in its own session,
# while the CLI takes over this process — its exit status and its blocking
# (--wait) are the caller's to see.
before=$(code_windows | cut -f1)
(retag_window </dev/null >/dev/null 2>&1 &)

exec "$cli" "${args[@]}"
